/**
 * A badge assignment represents the relationship between a badge and a member.
 * When a badge assignment is created, the specified member receives the badge
 * and any associated permissions or privileges.
 */
export interface BadgeAssignment {
  /**
   * Badge assignment ID.
   * @format GUID
   * @readonly
   */
  id?: string | null;
  /**
   * ID of the badge being assigned to the member. Call the [Badges API](https://dev.wix.com/docs/api-reference/crm/members-contacts/members/badges-v4/introduction) to retrieve available badges.
   * @format GUID
   */
  badgeId?: string | null;
  /**
   * ID of the member receiving the badge assignment. Call the [Members API](https://dev.wix.com/docs/api-reference/crm/members-contacts/members/members/introduction) to retrieve member information.
   * @format GUID
   */
  memberId?: string | null;
  /**
   * Date and time the badge assignment was created.
   * @readonly
   */
  createdDate?: Date | null;
  /**
   * Date and time the badge assignment was updated.
   * @readonly
   */
  updatedDate?: Date | null;
  /**
   * Tags allow you to classify ticket reservations.
   *
   * Learn more about [tags](https://dev.wix.com/docs/rest/business-management/tags/introduction).
   */
  tags?: Tags;
  /**
   * Extended fields allow you to add custom properties beyond the standard reservation data.
   *
   * Learn more about [extended fields](https://dev.wix.com/docs/build-apps/develop-your-app/extensions/backend-extensions/schema-plugins/about-schema-plugin-extensions).
   */
  extendedFields?: ExtendedFields;
}

/**
 * Common object for tags.
 * Should be use as in this example:
 * message Foo {
 * option (.wix.api.decomposite_of) = "wix.common.tags.Foo";
 * string id = 1;
 * ...
 * Tags tags = 5
 * }
 *
 * example of taggable entity
 * {
 * id: "123"
 * tags: {
 * tags: {
 * tag_ids:["11","22"]
 * },
 * private_tags: {
 * tag_ids: ["33", "44"]
 * }
 * }
 * }
 */
export interface Tags {
  /** Tags that require an additional permission in order to access them, normally not given to site members or visitors. */
  privateTags?: TagList;
  /** Tags that are exposed to anyone who has access to the labeled entity itself, including site members and visitors. */
  tags?: TagList;
}

export interface TagList {
  /**
   * List of tag IDs
   * @maxSize 100
   * @maxLength 5
   */
  tagIds?: string[];
}

export interface ExtendedFields {
  /**
   * Extended field data. Each key corresponds to the namespace of the app that created the extended fields.
   * The value of each key is structured according to the schema defined when the extended fields were configured.
   *
   * You can only access fields for which you have the appropriate permissions.
   *
   * Learn more about [extended fields](https://dev.wix.com/docs/rest/articles/getting-started/extended-fields).
   */
  namespaces?: Record<string, Record<string, any>>;
}

export interface TagsModified {
  /** Updated function. */
  badgeAssignment?: BadgeAssignment;
  /** Tags that were assigned to the Function. */
  assignedTags?: Tags;
  /** Tags that were unassigned from the Function. */
  unassignedTags?: Tags;
}

